      g.text(3,5,"KEEP floor Y "..plan.floorY,g.size-4,"5")
      g.text(3,7,"Layers "..plan.depth,g.size-4)
      g.text(3,8,"Cells "..plan.total,g.size-4)
      g.text(3,9,"Travel fuel "..plan.fuel,g.size-4)
      g.paragraph(11,"Cuts only. Returns home.",2,"8")
      g.button("checked",(self.checked and "[x] " or "[ ] ").."Placement checked",2,14,g.size-2,"checked")
      g.footer("Back","Start job","start",self.checked and writable(),true)
    elseif self.page == "cancel" then
      g.begin("CANCEL THIS JOB?","Turtle #"..self.selected)
      g.paragraph(5,"The turtle will stop in place. It will NOT return home.",4,"4")
      g.paragraph(11,"Pause instead if you want to resume this job later.",4,"8")
      g.footer("Back","Cancel job","confirmCancel",writable(),true)
    elseif self.page == "quit" then
      g.begin("CLOSE CONTROLLER?",client.group or "Turtle Fleet")
      g.paragraph(5,"Active turtles pause after 12 seconds without contact.",4,"4")
      g.paragraph(11,"Reopen this controller and choose Resume to continue.",4,"8")
      g.footer("Back","Quit","confirmQuit")
    elseif self.page == "pending" then
      g.begin("SENDING COMMAND","Turtle #"..self.selected)
      g.paragraph(5,"Waiting for the turtle to acknowledge the command.",4)
      g.paragraph(11,"Discovery and connection heartbeats are still active.",4,"8")
      g.text(3,16,"Attempt "..(client.pending and client.pending.attempts or 1).." of 3",g.size-4,"3")
    elseif self.page == "info" then
      g.begin(self.infoTitle,"Turtle #"..(self.selected or "-"))
      local lines=gui.wrap(self.infoText,g.size-4)
      local per=height-8
      local pages=math.max(1,math.ceil(#lines/per))
      self.infoPage=math.min(self.infoPage,pages)
      for i=(self.infoPage-1)*per+1,math.min(#lines,self.infoPage*per) do g.text(3,4+(i-1)%per,lines[i],g.size-4) end
      g.text(3,height-4,"Page "..self.infoPage.."/"..pages,g.size-4,"8")
      g.footer("Back",self.infoPage<pages and "More" or nil,"infoMore")
    else go("home",true); return self.render() end
    if self.error then
      local errorText=self.error; self.error=nil
      notice("CHECK INPUT",errorText)
      return self.render()
    end
    g.finish()
  end

  function self.event(event,a,b,c)
    if event=="term_resize" then g.previous={} end
    if client.result then
      local result=client.result; client.result=nil
      go("detail",true)
      if not result.ok then notice("COMMAND RESULT",result.error) end
      return
    end
    if self.tooSmall then
      if event=="key" and a==keys.escape then self.running=false end
      return
    end
    if self.page=="pending" then return end
    local action=g.event(event,a,b,c)
    if event=="mouse_scroll" and self.page=="home" and display.isColor() then action=a>0 and "more" or "prev" end
    if not action then return end
    if action=="back" then
      if self.page=="home" or (self.page=="setup" and not client.group) then go("quit") else back() end
    elseif action=="setup" then self.group=client.group; go("setup")
    elseif action=="save" then
      if not self.group:match("^[%w_-]+$") or #self.group>32 then self.error="Use 1-32 letters, digits, - or _."
      else options.saveGroup(self.group); client.setGroup(self.group); go("home",true) end
    elseif action=="quit" then go("quit")
    elseif action=="confirmQuit" then self.running=false
    elseif action=="prev" or action=="more" then
      self.listPage=math.max(1,math.min(self.pages,self.listPage+(action=="more" and 1 or -1))); g.focus=nil
    elseif action:match("^open:") then self.selected=tonumber(action:sub(6)); go("detail")
    elseif action=="new" and writable() then
      local s=peer().status
      if s.active or not s.mining then return end
      self.revision,self.session=s.revision,s.session
      self.draft,self.checked,self.plan={},false,nil
      g.cursors={}; go("program")
    elseif action=="details" then
      local s=peer().status
      local position=s.pose and (" Position: X "..s.pose.x..", Y "..s.pose.y..", Z "..s.pose.z.." ("..s.pose.frame..").") or ""
      notice("TURTLE DETAILS",s.label..". "..s.state..". "..s.reason..position.." Owner #"..s.owner..". "..
        (s.mining and "Mining pickaxe equipped." or "Equip a diamond pickaxe to enable jobs."))
    elseif action=="flatten" or action=="quarry" then
      self.draft.program=action
      if action=="flatten" then self.draft.world=true; go("placement") else go("mode") end
    elseif action=="world" or action=="local" then self.draft.world=action=="world"; go("placement")
    elseif action:match("^heading:") then self.draft.heading=tonumber(action:sub(9))
    elseif action=="gps" then self.draft.verifyGPS=not self.draft.verifyGPS
    elseif action=="next" then nextPage()
    elseif action=="checked" then self.checked=not self.checked
    elseif action=="start" and self.checked then
      local p=peer()
      if not writable() or p.status.session~=self.session or p.status.revision~=self.revision or p.status.active then
        notice("TURTLE CHANGED","Turtle changed or went offline. Go back to the turtle dashboard and review a new job.")
      else command({action="start",spec=self.spec,pose=self.pose,verifyGPS=self.draft.verifyGPS==true,
        session=self.session,revision=self.revision}) end
    elseif action=="pause" or action=="resume" then command({action=action,jobId=peer().status.jobId})
    elseif action=="cancel" then self.cancelJob=peer().status.jobId; go("cancel")
    elseif action=="confirmCancel" then command({action="cancel",jobId=self.cancelJob})
    elseif action=="infoMore" then self.infoPage=self.infoPage+1 end
  end
  return self
end

return M

end
factories["fleet.gui"] = function()
-- Retained focus and editing state over an immediate-mode, cell-based display.
-- Rendering uses term.blit, never print/read, so content cannot scroll the screen.
local M = {}

function M.clean(text)
  return tostring(text or ""):gsub("[%z\1-\31\127-\255]", " ")
end

function M.wrap(text, width)
  local lines, line = {}, ""
  for word in M.clean(text):gmatch("%S+") do
    if #line > 0 and #line + #word + 1 > width then lines[#lines + 1], line = line, "" end
    while #word > width do
      if #line > 0 then lines[#lines + 1], line = line, "" end
      lines[#lines + 1], word = word:sub(1, width), word:sub(width + 1)
    end
    if #word > 0 then line = line == "" and word or line .. " " .. word end
  end
  if #line > 0 then lines[#lines + 1] = line end
  return lines
end

function M.new(display, keys)
  local self = { widgets = {}, focus = nil, cursors = {}, shift = false, ctrl = false, previous = {} }
  local fg, bg

  function self.begin(title, subtitle)
    self.width, self.height = display.getSize()
    self.color = display.isColor()
    self.left = math.floor((self.width - math.min(40, self.width)) / 2) + 1
    self.size = math.min(40, self.width)
    self.rows, self.widgets = {}, {}
    for y = 1, self.height do
      self.rows[y] = { text = string.rep(" ", self.width), fg = string.rep("0", self.width), bg = string.rep("f", self.width) }
    end
    self.fill(1, 1, self.size, 1, self.color and "b" or "0")
    self.text(2, 1, title, self.size - 2, self.color and "0" or "f", self.color and "b" or "0")
    self.text(2, 2, subtitle or "", self.size - 2, "8")
    self.text(2, self.height, "Tab/Arrows Enter Esc", self.size - 2, "8")
  end

  local function splice(value, x, text) return value:sub(1, x - 1) .. text .. value:sub(x + #text) end

  function self.text(x, y, text, width, color, background)
    if y < 1 or y > self.height then return end
    local absolute = x + self.left - 1
    local value = M.clean(text):sub(1, math.max(0, math.min(width or self.size, self.size - x + 1)))
    if absolute < 1 then value, absolute = value:sub(2 - absolute), 1 end
    value = value:sub(1, math.max(0, self.width - absolute + 1))
    if #value == 0 then return end
    local row = self.rows[y]
    color = color or "0"
    if not self.color and color ~= "0" and color ~= "7" and color ~= "8" and color ~= "f" then color = "0" end
    row.text = splice(row.text, absolute, value)
    row.fg = splice(row.fg, absolute, string.rep(color, #value))
    if background then row.bg = splice(row.bg, absolute, string.rep(background, #value)) end
  end

  function self.fill(x, y, width, height, color)
    for row = y, y + height - 1 do self.text(x, row, string.rep(" ", width), width, "0", color) end
  end

  function self.paragraph(y, text, count, color)
    for i, line in ipairs(M.wrap(text, self.size - 4)) do
      if i > count then break end
      self.text(3, y + i - 1, line, self.size - 4, color)
    end
  end

  function self.button(id, label, x, y, width, action, options)
    options = options or {}
    self.widgets[#self.widgets + 1] = {
      id = id, label = label, x = x, y = y, width = width, height = options.height or 2,
      action = action or id, enabled = options.enabled ~= false, danger = options.danger,
      sub = options.sub, primary=options.primary, kind = "button",
    }
  end

  function self.field(id, label, y, value, change, options)
    options = options or {}
    self.text(3, y, label, self.size - 4, "8")
    self.widgets[#self.widgets + 1] = {
      id = id, x = 3, y = y + 1, width = self.size - 4, height = 2,
      value = value, change = change, numeric = options.numeric, max = options.max or 12,
      enabled = true, kind = "field", enter = options.enter,
    }
  end

  function self.footer(backLabel, nextLabel, nextAction, enabled, danger)
    local half = math.floor((self.size - 5) / 2)
    self.button("back", backLabel or "Back", 2, self.height - 2, half, "back")
    if nextLabel then
      self.button("next", nextLabel, 4 + half, self.height - 2, self.size - half - 4,
        nextAction or "next", { enabled = enabled, danger = danger })
    end
  end

  function self.progress(y, done, total)
    local width = self.size - 4
    local filled = total > 0 and math.floor(math.min(1, done / total) * width) or 0
    self.text(3, y, string.rep("#", filled) .. string.rep("-", width - filled), width, self.color and "5" or "0")
  end

  function self.find(id)
    for i, widget in ipairs(self.widgets) do if widget.id == id then return widget, i end end
  end

  function self.moveFocus(amount)
    local _, current = self.find(self.focus)
    current = current or (amount > 0 and 0 or 1)
    for _ = 1, #self.widgets do
      current = (current - 1 + amount) % #self.widgets + 1
      if self.widgets[current].enabled then self.focus = self.widgets[current].id; return end
    end
    self.focus = nil
  end

  function self.finish()
    local focus = self.find(self.focus)
    if not focus or not focus.enabled then self.moveFocus(1) end
    self.cursor = nil
    for _, w in ipairs(self.widgets) do
      local selected = self.focus == w.id
      bg = not w.enabled and "f" or selected and (self.color and "b" or "0") or "7"
      fg = not w.enabled and "8" or selected and not self.color and "f" or "0"
      if w.danger and w.enabled and self.color and not selected then bg = "e" end
      if w.primary and w.enabled and self.color then bg="b" end
      self.fill(w.x, w.y, w.width, w.height, bg)
      if w.kind == "field" then
        local cursor = math.min(self.cursors[w.id] or #w.value, #w.value)
        self.cursors[w.id] = cursor
        local offset = math.max(0, cursor - (w.width - 3))
        self.text(w.x, w.y, selected and ">" or " ", 1, fg, bg)
        self.text(w.x + 1, w.y, w.value:sub(offset + 1), w.width - 2, fg, bg)
        if selected then self.cursor = { x = self.left + w.x + cursor - offset, y = w.y } end
      else
        self.text(w.x, w.y, selected and ">" or " ", 1, fg, bg)
        self.text(w.x + 1, w.y, w.label, w.width - 2, fg, bg)
        if w.sub then self.text(w.x + 1, w.y + 1, w.sub, w.width - 2, fg, bg) end
      end
    end
    display.setCursorBlink(false)
    for y, row in ipairs(self.rows) do
      local signature = row.text .. row.fg .. row.bg
      if self.previous[y] ~= signature then
        display.setCursorPos(1, y)
        display.blit(row.text, row.fg, row.bg)
        self.previous[y] = signature
      end
    end
    for y = self.height + 1, #self.previous do self.previous[y] = nil end
    if self.cursor then display.setCursorPos(self.cursor.x, self.cursor.y); display.setCursorBlink(true) end
  end

  local function insert(w, text)
    text = M.clean(text)
    local pos = self.cursors[w.id] or #w.value
    local updated = w.value:sub(1, pos) .. text .. w.value:sub(pos + 1)
    if #updated > w.max or (w.numeric and not updated:match("^%-?%d*$")) then return end
    w.change(updated)
    self.cursors[w.id] = pos + #text
  end

  function self.event(event, a, b, c)
    local w = self.find(self.focus)
    if event == "term_resize" then self.previous = {}; return end
    if event == "key_up" then
      if a == keys.leftShift or a == keys.rightShift then self.shift = false end
      if a == keys.leftCtrl or a == keys.rightCtrl then self.ctrl = false end
    elseif event == "mouse_click" and a == 1 and self.color then
      local x = b - self.left + 1
      for _, widget in ipairs(self.widgets) do
        if widget.enabled and x >= widget.x and x < widget.x + widget.width
          and c >= widget.y and c < widget.y + widget.height then
          self.focus = widget.id
          if widget.kind == "button" then return widget.action end
          local old = self.cursors[widget.id] or #widget.value
          local offset = math.max(0, old - (widget.width - 3))
          self.cursors[widget.id] = math.max(0, math.min(#widget.value, x - widget.x - 1 + offset))
          return
        end
      end
    elseif event == "key" then
      if b == true and (a == keys.enter or a == keys.numPadEnter or a == keys.space) then return end
      if a == keys.leftShift or a == keys.rightShift then self.shift = true; return end
      if a == keys.leftCtrl or a == keys.rightCtrl then self.ctrl = true; return end
      if a == keys.escape then return "back" end
      if a == keys.tab then self.moveFocus(self.shift and -1 or 1); return end
      if a == keys.up or a == keys.down then self.moveFocus(a == keys.up and -1 or 1); return end
      if w and w.kind == "field" then
        local pos = self.cursors[w.id] or #w.value
        if a == keys.left then self.cursors[w.id] = math.max(0, pos - 1)
        elseif a == keys.right then self.cursors[w.id] = math.min(#w.value, pos + 1)
        elseif a == keys.home then self.cursors[w.id] = 0
        elseif a == keys["end"] then self.cursors[w.id] = #w.value
        elseif a == keys.backspace and pos > 0 then
          w.change(w.value:sub(1, pos - 1) .. w.value:sub(pos + 1)); self.cursors[w.id] = pos - 1
        elseif a == keys.delete then w.change(w.value:sub(1, pos) .. w.value:sub(pos + 2))
        elseif a == keys.u and self.ctrl then w.change(""); self.cursors[w.id] = 0
        elseif a == keys.enter or a == keys.numPadEnter then self.focus = w.enter or "next" end
      elseif a == keys.left or a == keys.right then self.moveFocus(a == keys.left and -1 or 1)
      elseif (a == keys.enter or a == keys.numPadEnter or a == keys.space) and w and w.enabled then return w.action end
    elseif (event == "char" or event == "paste") and w and w.kind == "field" and not self.ctrl then insert(w, a)
    end
  end
  return self
end

return M

end
factories["fleet.net"] = function()
local M = { VERSION = 1, PROTOCOL = "turtle-fleet/1", LEASE = 12, STALE = 8 }

function M.open()
  local count = 0
  for _, side in ipairs(peripheral.getNames()) do
    if peripheral.hasType(side, "modem") and peripheral.call(side, "isWireless") then
      rednet.open(side)
      count = count + 1
    end
  end
  assert(count > 0, "Attach a wireless or Ender modem, then run Fleet again.")
end

function M.valid(message, group)
  return type(message) == "table" and message.version == M.VERSION
    and message.group == group and type(message.kind) == "string"
end

function M.packet(group, kind, body)
  local packet = body or {}
  packet.version, packet.group, packet.kind = M.VERSION, group, kind
  return packet
end

function M.send(id, group, kind, body)
  return rednet.send(id, M.packet(group, kind, body), M.PROTOCOL)
end

function M.broadcast(group, kind, body)
  rednet.broadcast(M.packet(group, kind, body), M.PROTOCOL)
end

return M

end
factories["fleet.planner"] = function()
-- All geometry is independent of Minecraft, and uses inclusive block coordinates.
local M = {}
M.MAX_EDGE, M.MAX_DEPTH, M.MAX_VOLUME = 256, 384, 2000000
M.directions = {
  [0] = { x = 0, z = -1, name = "north" },
  [1] = { x = 1, z = 0, name = "east" },
  [2] = { x = 0, z = 1, name = "south" },
  [3] = { x = -1, z = 0, name = "west" },
}
M.programs = {
  { id = "flatten", name = "Flatten by corners", needsWorld = true },
  { id = "quarry", name = "Clear width/length/depth", needsWorld = false },
}

function M.integer(n, low, high)
  return type(n) == "number" and n == n and n % 1 == 0 and n >= low and n <= high
end

function M.validPose(p)
  return type(p) == "table" and M.integer(p.x, -30000000, 30000000)
    and M.integer(p.z, -30000000, 30000000) and M.integer(p.y, -30000, 30000)
    and M.integer(p.heading, 0, 3) and (p.frame == "world" or p.frame == "local")
end

function M.copyPose(p)
  return { x = p.x, y = p.y, z = p.z, heading = p.heading, frame = p.frame }
end

function M.create(spec, pose)
  if type(spec) ~= "table" or not M.validPose(pose) then
    return nil, "Invalid job or starting position."
  end
  local p = { origin = M.copyPose(pose), program = spec.program }
  if spec.program == "flatten" then
    if pose.frame ~= "world" then return nil, "Corners require world coordinates." end
    for _, key in ipairs({ "x1", "z1", "x2", "z2" }) do
      if not M.integer(spec[key], -30000000, 30000000) then
        return nil, "Corner coordinates must be whole numbers."
      end
    end
    if not M.integer(spec.floorY, -30000, 30000) then return nil, "Invalid floor Y." end
    if (pose.x ~= spec.x1 and pose.x ~= spec.x2)
      or (pose.z ~= spec.z1 and pose.z ~= spec.z2) then
      return nil, "Place the turtle above a corner of this rectangle."
    end
    local otherX = pose.x == spec.x1 and spec.x2 or spec.x1
    local otherZ = pose.z == spec.z1 and spec.z2 or spec.z1
    p.width, p.length = math.abs(otherX - pose.x) + 1, math.abs(otherZ - pose.z) + 1
    p.u = { x = otherX >= pose.x and 1 or -1, z = 0 }
    p.v = { x = 0, z = otherZ >= pose.z and 1 or -1 }
    p.depth = pose.y - 1 - spec.floorY
  elseif spec.program == "quarry" then
    p.width, p.length, p.depth = spec.width, spec.length, spec.depth
    p.u, p.v = M.directions[(pose.heading + 1) % 4], M.directions[pose.heading]
  else
    return nil, "Unknown program."
  end
  if not M.integer(p.width, 1, M.MAX_EDGE) or not M.integer(p.length, 1, M.MAX_EDGE) then
    return nil, "Width and length must be 1-256 blocks (corners are inclusive)."
  end
  if not M.integer(p.depth, 1, M.MAX_DEPTH) then
    return nil, "Remove 1-384 layers; floor Y must be at least 2 below the turtle."
  end
  p.area, p.total = p.width * p.length, p.width * p.length * p.depth
  if p.total > M.MAX_VOLUME then return nil, "Job exceeds 2,000,000 blocks." end
  p.topY, p.floorY = pose.y - 1, pose.y - p.depth - 1
  local farX = pose.x + p.u.x * (p.width - 1) + p.v.x * (p.length - 1)
  local farZ = pose.z + p.u.z * (p.width - 1) + p.v.z * (p.length - 1)
  if not M.integer(farX, -30000000, 30000000) or not M.integer(farZ, -30000000, 30000000)
    or not M.integer(p.floorY, -30000, 30000) then return nil, "Area is outside coordinate limits." end
  p.minX, p.maxX = math.min(pose.x, farX), math.max(pose.x, farX)
  p.minZ, p.maxZ = math.min(pose.z, farZ), math.max(pose.z, farZ)
  local last = M.target(p, p.total)
  p.fuel = p.total + math.abs(last.x - pose.x) + math.abs(last.z - pose.z) + p.depth
  return p
end

-- Adjacent serpentine layers run in opposite directions. No path table is allocated.
function M.target(p, index)
  assert(M.integer(index, 1, p.total), "Invalid route index")
  local layer = math.floor((index - 1) / p.area)
  local cell = (index - 1) % p.area
  if layer % 2 == 1 then cell = p.area - 1 - cell end
  local row, column = math.floor(cell / p.width), cell % p.width
  if row % 2 == 1 then column = p.width - 1 - column end
  return {
    x = p.origin.x + p.u.x * column + p.v.x * row,
    z = p.origin.z + p.u.z * column + p.v.z * row,
    y = p.topY - layer,
  }
end

function M.contains(p, target)
  return target.x >= p.minX and target.x <= p.maxX and target.z >= p.minZ
    and target.z <= p.maxZ and target.y > p.floorY and target.y <= p.topY
end

return M

end
factories["fleet.ui"] = function()
local M = {}

function M.header(title)
  term.clear()
  term.setCursorPos(1, 1)
  print(title)
  local width = term.getSize()
  print(string.rep("-", width))
end

function M.text(label, default)
  print(label .. (default ~= nil and " [" .. tostring(default) .. "]" or ""))
  write("> ")
  local value = read()
  if value == "" and default ~= nil then return tostring(default) end
  return value
end

function M.number(label, default, low, high)
  while true do
    local value = tonumber(M.text(label, default))
    if value and value == value and value % 1 == 0 and value >= low and value <= high then return value end
    print("Whole number: " .. low .. " to " .. high)
  end
end

function M.wait()
  print("Press Enter to continue.")
  read()
end

function M.load(path)
  if not fs.exists(path) then return nil end
  local file = fs.open(path, "r")
  if not file then return nil end
  local value = textutils.unserialize(file.readAll())
  file.close()
  return value
end

function M.save(path, value)
  local file = assert(fs.open(path, "w"), "Cannot save " .. path)
  file.write(textutils.serialize(value))
  file.close()
end

function M.group(default)
  while true do
    local value = M.text("Fleet name", default or "fleet")
    if value:match("^[%w_-]+$") and #value <= 32 then return value end
    print("Use 1-32 letters, digits, - or _.")
  end
end

return M

end
local net = require("fleet.net")
local ui = require("fleet.ui")
local clientModule = require("fleet.client")
local dashboard = require("fleet.dashboard")
local args = { ... }
net.open()
local path = "/.fleet-controller"
local config = ui.load(path)
local group = type(config)=="table" and type(config.group)=="string" and config.group or nil
local client = clientModule.new({ group=group, owner=os.getComputerID(), now=os.clock,
  boot=tostring(os.getComputerID())..":"..tostring(os.epoch("utc")) })
local app = dashboard.new(term,keys,{ client=client, setup=not group or args[1]=="setup",
  saveGroup=function(value) ui.save(path,{group=value}) end })

-- One event loop keeps editing, discovery, heartbeats and retries responsive together.
local timer=os.startTimer(0.25)
local ok,why=pcall(function()
  client.tick()
  app.render()
  while app.running do
    local event={os.pullEvent()}
    if event[1]=="rednet_message" and event[4]==net.PROTOCOL then client.receive(event[2],event[3]) end
    if event[1]=="timer" and event[2]==timer then client.tick(); timer=os.startTimer(0.25) end
    app.event(table.unpack(event))
    if app.running then app.render() end
  end
end)
os.cancelTimer(timer)
term.setCursorBlink(false)
term.setBackgroundColor(colors.black)
term.setTextColor(colors.white)
term.clear()
term.setCursorPos(1,1)
if not ok then error(why,0) end
print("Controller closed. Active turtles pause after their connection lease expires.")
